<h1><?= te('Import employee spreadsheets') ?></h1><p class="sub"><?= te('CSV and XLSX · preview and map identity, employee category, payment method, ADP ID, assignment dates, shift and rates. Unknown columns stay encrypted for review. Hotel, vehicle and historical finance records require separate reconciliation.') ?></p><?php if($error): ?><div class="flash err"><?= e($error) ?></div><?php endif; ?><form class="card" method="post" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="do" value="preview"><label><?= te('Employee roster file') ?></label><input name="sheet" type="file" accept=".csv,.xlsx" required><button class="btn"><?= te('Preview file') ?></button></form>
<?php if($preview): ?><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="commit"><h2><?= e($preview['filename']) ?> · <?= count($preview['data']) ?> rows</h2><p><?= te('Rows are added as new identities and offered assignments in the selected project. Matching employee IDs/emails go into review without changing existing records.') ?></p><div class="grid g2"><?php foreach($fields as $field): ?><div><label><?= e($field) ?></label><select name="mapping[<?= e($field) ?>]"><option value=""><?= te('Not mapped') ?></option><?php foreach($preview['headers'] as $i=>$header): ?><option value="<?= $i ?>"><?= e($header) ?></option><?php endforeach; ?></select></div><?php endforeach; ?></div><div class="scroll"><table><tr><?php foreach($preview['headers'] as $h): ?><th><?= e($h) ?></th><?php endforeach; ?></tr><?php foreach(array_slice($preview['data'],0,5) as $line): ?><tr><?php foreach($line as $value): ?><td><?= e($value) ?></td><?php endforeach; ?></tr><?php endforeach; ?></table></div><button class="btn"><?= te('Import mapped records') ?></button></form><?php endif; ?>
<div class="card"><h2><?= te('Import audit') ?></h2><?php foreach($batches as $b): ?><p><?= e($b['filename']) ?> · <?= (int)$b['row_count'] ?> source rows · <?= (int)$b['imported'] ?> imported · <?= (int)$b['duplicates'] ?> duplicate reviews · <?= (int)$b['invalid'] ?> invalid</p><?php endforeach; ?></div><div class="card"><h2><?= te('Rows needing review') ?></h2><?php foreach($reviews as $r): ?><p>Batch <?= (int)$r['batch_id'] ?> · row <?= (int)$r['row_number'] ?> · <?= e($r['status'].' · '.$r['full_name'].' · '.$r['note']) ?></p><?php endforeach; ?></div>